import React, { useState, useEffect } from 'react';
import { Play, ShoppingCart, Eye, Share2, User } from 'lucide-react';
import Recherche from './Recherche';
import Lecteur from './Lecteur';
import Partager from './Partager';
import './Catalogue.css';

function Catalogue({ allerVers, utilisateur }) {
  const [musiques, setMusiques] = useState([]);
  const [chargement, setChargement] = useState(true);
  const [filtre, setFiltre] = useState('tous');
  const [pisteActive, setPisteActive] = useState(null);
  const [playlist, setPlaylist] = useState([]);
  const [partagerMusique, setPartagerMusique] = useState(null);

  useEffect(() => {
    fetch('/api/musiques')
      .then(res => res.json())
      .then(data => {
        setMusiques(data.musiques);
        setChargement(false);
      })
      .catch(() => setChargement(false));
  }, []);

  const genres = ['tous', ...new Set(musiques.map(m => m.genre).filter(Boolean))];
  const musiquesFiltrees = filtre === 'tous' ? musiques : musiques.filter(m => m.genre === filtre);

  const jouerExtrait = (musique) => {
    const singles = musiquesFiltrees.filter(m => m.type === 'single' && m.fichier_url);
    const playlistSingles = singles.map(m => ({
      url: m.fichier_url,
      titre: m.titre,
      artiste: m.nom_artiste,
      pochette: m.pochette_url,
      id: m.id,
      estExtrait: true
    }));
    setPlaylist(playlistSingles);
    setPisteActive({
      url: musique.fichier_url,
      titre: musique.titre,
      artiste: musique.nom_artiste,
      pochette: musique.pochette_url,
      id: musique.id,
      estExtrait: true
    });
  };

  return (
    <div className="catalogue-page">
      <header className="header">
        <div className="logo" onClick={() => allerVers('accueil')}>Varim Music</div>
        <nav className="nav">
          <a href="#" onClick={() => allerVers('accueil')}>Accueil</a>
          <a href="#" onClick={() => allerVers('nouveautes')}>Nouveautés</a>
          <a href="#" onClick={() => allerVers('topventes')}>Top Ventes</a>
          <a href="#" className="actif">Catalogue</a>
        </nav>
        <div className="auth-buttons">
          {utilisateur ? (
            <>
              <span className="user-prenom">{utilisateur.prenom}</span>
              {utilisateur.role === 'artiste' && (
                <button className="btn-dashboard" onClick={() => allerVers('upload')}>+ Publier</button>
              )}
              <button className="btn-login" onClick={() => {
                localStorage.removeItem('token');
                localStorage.removeItem('utilisateur');
                allerVers('accueil');
              }}>Déconnexion</button>
            </>
          ) : (
            <>
              <button className="btn-login" onClick={() => allerVers('login')}>Connexion</button>
              <button className="btn-register" onClick={() => allerVers('register')}>S'inscrire</button>
            </>
          )}
        </div>
      </header>

      <div className="catalogue-contenu">
        <div className="catalogue-top">
          <h1 className="catalogue-titre">Catalogue</h1>
          <Recherche musiques={musiques} allerVers={allerVers} />
        </div>

        <div className="filtres">
          {genres.map(genre => (
            <button
              key={genre}
              className={`filtre-btn ${filtre === genre ? 'actif' : ''}`}
              onClick={() => setFiltre(genre)}
            >
              {genre === 'tous' ? 'Tous' : genre}
            </button>
          ))}
        </div>

        {chargement ? (
          <div className="chargement">Chargement des musiques...</div>
        ) : musiquesFiltrees.length === 0 ? (
          <div className="vide">Aucune musique disponible.</div>
        ) : (
          <div className="grille-musiques">
            {musiquesFiltrees.map(musique => (
              <div key={musique.id} className="carte-musique">
                <div className="carte-pochette">
                  {musique.pochette_url ? (
                    <img src={musique.pochette_url} alt={musique.titre} />
                  ) : (
                    <div className="pochette-defaut">♪</div>
                  )}
                  <div className="carte-type">{musique.type}</div>
                </div>

                <div className="carte-infos">
                  <h3 className="carte-titre">{musique.titre}</h3>
                  <p
                    className="carte-artiste"
                    onClick={() => allerVers('profil_' + musique.artiste_id)}
                  >
                    <User size={12} /> {musique.nom_artiste}
                  </p>
                  <p className="carte-genre">{musique.genre}</p>
                  <p className="carte-prix">{musique.prix} FCFA</p>
                </div>

                <div className="carte-actions">
                  {musique.type === 'album' ? (
                    <button className="btn-extrait" onClick={() => allerVers('album_' + musique.id)}>
                      <Eye size={14} /> Voir
                    </button>
                  ) : (
                    <button
                      className={`btn-extrait ${pisteActive?.id === musique.id ? 'en-lecture' : ''}`}
                      onClick={() => jouerExtrait(musique)}
                    >
                      <Play size={14} /> Extrait
                    </button>
                  )}
                  <button className="btn-acheter" onClick={() => allerVers('achat_' + musique.id)}>
                    <ShoppingCart size={14} />
                  </button>
                  <button className="btn-partager" onClick={() => setPartagerMusique(musique)}>
                    <Share2 size={14} />
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {pisteActive && (
        <Lecteur
          piste={pisteActive}
          playlist={playlist}
          onPisteChange={setPisteActive}
          onFermer={() => { setPisteActive(null); setPlaylist([]); }}
        />
      )}

      {partagerMusique && (
        <Partager
          lien={`${window.location.origin}?musique=${partagerMusique.id}`}
          titre={`${partagerMusique.titre} - ${partagerMusique.nom_artiste}`}
          onFermer={() => setPartagerMusique(null)}
        />
      )}
    </div>
  );
}

export default Catalogue;
